[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <!-- Primary Meta Tags -->
  <title>Creative Classes Taught by the Best Creative Pros | CreativeHub</title>
  <meta name="title" content="Creative Classes Taught by the Best Creative Pros | CreativeHub">
  <meta name="description" content="Join 425k+ creatives on CreativeHub. Thousands of online classes in illustration, design, photography, film & more. Start your 7-day free trial today.">
  <meta name="keywords" content="online creative classes, illustration courses, design classes, photography lessons, digital art, online learning">
  <meta name="author" content="CreativeHub">
  <meta name="robots" content="index, follow">

  <!-- Canonical URL -->
  <link rel="canonical" href="https://www.creativehub.com/">

  <!-- Open Graph / Facebook -->
  <meta property="og:type" content="website">
  <meta property="og:url" content="https://www.creativehub.com/">
  <meta property="og:title" content="Creative Classes Taught by the Best Creative Pros | CreativeHub">
  <meta property="og:description" content="Join 425k+ creatives on CreativeHub. Thousands of online classes in illustration, design, photography, film & more. Start your 7-day free trial today.">
  <meta property="og:image" content="https://www.creativehub.com/og-image.jpg">
  <meta property="og:site_name" content="CreativeHub">

  <!-- Twitter -->
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://www.creativehub.com/">
  <meta property="twitter:title" content="Creative Classes Taught by the Best Creative Pros | CreativeHub">
  <meta property="twitter:description" content="Join 425k+ creatives on CreativeHub. Thousands of online classes in illustration, design, photography, film & more. Start your 7-day free trial today.">
  <meta property="twitter:image" content="https://www.creativehub.com/og-image.jpg">

  <!-- Structured Data: EducationalOrganization + FAQPage -->
  <script type="application/ld+json">
  [
    {
      "@context": "https://schema.org",
      "@type": "EducationalOrganization",
      "name": "CreativeHub",
      "description": "An online learning community offering thousands of creative classes taught by industry professionals, from illustration and design to photography and filmmaking.",
      "@id": "https://www.creativehub.com/#organization",
      "url": "https://www.creativehub.com",
      "image": "https://www.creativehub.com/og-image.jpg",
      "logo": "https://www.creativehub.com/logo.svg",
      "sameAs": [
        "https://www.instagram.com/creativehub",
        "https://www.tiktok.com/@creativehub",
        "https://www.youtube.com/creativehub"
      ],
      "offers": {
        "@type": "Offer",
        "name": "CreativeHub Membership",
        "description": "Unlimited access to thousands of creative classes",
        "availability": "https://schema.org/InStock",
        "priceSpecification": {
          "@type": "UnitPriceSpecification",
          "price": "0",
          "priceCurrency": "USD",
          "description": "7-day free trial"
        }
      }
    },
    {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is CreativeHub?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "CreativeHub is an online learning community with thousands of classes for creative and curious people, on topics including illustration, design, photography, video, freelancing, and more."
          }
        },
        {
          "@type": "Question",
          "name": "What is included in my membership?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "As a CreativeHub member, you'll have unlimited access to all classes to watch when and where you want, plus offline viewing, access to a vibrant community of lifelong learners, and more."
          }
        },
        {
          "@type": "Question",
          "name": "What can I learn?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "CreativeHub has thousands of classes in everything from graphic design to cooking, productivity, filmmaking, content creation, UI/UX design, marketing, crafts, music, social media, and entrepreneurship."
          }
        },
        {
          "@type": "Question",
          "name": "What happens after my trial is over?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "After your trial ends, your annual CreativeHub membership begins. You'll be billed for the year in full, so you can enjoy continuous access to creative classes year-round."
          }
        },
        {
          "@type": "Question",
          "name": "Can I teach on the platform?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes! CreativeHub teachers are everyday creatives and professionals who want to share their passion and the skills they've gained with a community of eager learners."
          }
        }
      ]
    },
    {
      "@context": "https://schema.org",
      "@type": "WebSite",
      "name": "CreativeHub",
      "url": "https://www.creativehub.com",
      "potentialAction": {
        "@type": "SearchAction",
        "target": "https://www.creativehub.com/search?q={search_term_string}",
        "query-input": "required name=search_term_string"
      }
    }
  ]
  </script>

  <!-- Fonts -->
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">

  <style>
    /* ── Reset & Base ── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Plus Jakarta Sans', system-ui, sans-serif;
      background: #fff;
      color: #111;
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* ── CSS Variables ── */
    :root {
      --black: #000000;
      --green: #55DA9B;
      --purple: #5620C1;
      --purple-light: #7B4FD8;
      --hero-bg: #09090F;
      --card-bg: #161622;
      --dark-section: #0D0D16;
      --text-muted: #9090A8;
      --border: rgba(255,255,255,0.08);
      --border-light: #E8E8F0;
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
      --radius-xl: 28px;
    }

    /* ── Utility ── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .container--wide { max-width: 1360px; margin: 0 auto; padding: 0 24px; }

    /* ── Nav ── */
    .nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(9,9,15,0.92);
      backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border);
    }
    .nav__inner {
      display: flex;
      align-items: center;
      gap: 32px;
      height: 64px;
      max-width: 1360px;
      margin: 0 auto;
      padding: 0 24px;
    }
    .nav__logo {
      font-size: 20px;
      font-weight: 800;
      color: #fff;
      text-decoration: none;
      letter-spacing: -0.5px;
      flex-shrink: 0;
    }
    .nav__logo span { color: var(--green); }
    .nav__links {
      display: flex;
      gap: 4px;
      margin-left: 8px;
    }
    .nav__links a {
      color: rgba(255,255,255,0.7);
      text-decoration: none;
      font-size: 14px;
      font-weight: 500;
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      transition: color 0.2s, background 0.2s;
    }
    .nav__links a:hover { color: #fff; background: rgba(255,255,255,0.08); }
    .nav__spacer { flex: 1; }
    .nav__actions { display: flex; align-items: center; gap: 8px; }
    .btn-ghost-white {
      background: transparent;
      border: none;
      color: rgba(255,255,255,0.8);
      font-family: inherit;
      font-size: 14px;
      font-weight: 500;
      padding: 8px 16px;
      border-radius: var(--radius-sm);
      cursor: pointer;
      transition: color 0.2s, background 0.2s;
      text-decoration: none;
    }
    .btn-ghost-white:hover { color: #fff; background: rgba(255,255,255,0.08); }
    .btn-primary-nav {
      background: var(--green);
      color: #000;
      font-family: inherit;
      font-size: 14px;
      font-weight: 700;
      padding: 8px 20px;
      border: none;
      border-radius: var(--radius-sm);
      cursor: pointer;
      transition: transform 0.15s, opacity 0.15s;
      text-decoration: none;
    }
    .btn-primary-nav:hover { opacity: 0.9; transform: translateY(-1px); }

    /* ── Hero ── */
    .hero {
      background: var(--hero-bg);
      position: relative;
      overflow: hidden;
      padding: 80px 24px 72px;
      text-align: center;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 70% 50% at 15% 60%, rgba(86,32,193,0.25) 0%, transparent 70%),
        radial-gradient(ellipse 60% 40% at 85% 30%, rgba(85,218,155,0.12) 0%, transparent 70%),
        radial-gradient(ellipse 50% 60% at 50% 100%, rgba(86,32,193,0.15) 0%, transparent 60%);
      pointer-events: none;
    }
    .hero__badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(85,218,155,0.12);
      border: 1px solid rgba(85,218,155,0.25);
      color: var(--green);
      font-size: 13px;
      font-weight: 600;
      padding: 6px 14px;
      border-radius: 100px;
      margin-bottom: 24px;
      position: relative;
    }
    .hero__badge::before {
      content: '';
      width: 6px;
      height: 6px;
      background: var(--green);
      border-radius: 50%;
      display: inline-block;
    }
    .hero__title {
      font-size: clamp(38px, 6vw, 72px);
      font-weight: 800;
      color: #fff;
      line-height: 1.08;
      letter-spacing: -2px;
      max-width: 780px;
      margin: 0 auto 20px;
      position: relative;
    }
    .hero__title .highlight {
      background: linear-gradient(135deg, var(--green) 0%, #7BEFC0 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero__subtitle {
      font-size: 20px;
      font-weight: 600;
      color: rgba(255,255,255,0.65);
      margin-bottom: 40px;
      position: relative;
    }
    .hero__ctas {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      max-width: 400px;
      margin: 0 auto 16px;
      position: relative;
    }
    .btn-google, .btn-email {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      width: 100%;
      padding: 15px 28px;
      border-radius: var(--radius-md);
      font-family: inherit;
      font-size: 15px;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.15s, box-shadow 0.15s;
      border: none;
      text-decoration: none;
    }
    .btn-google {
      background: #fff;
      color: #111;
      box-shadow: 0 2px 16px rgba(0,0,0,0.3);
    }
    .btn-google:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(0,0,0,0.4); }
    .btn-email {
      background: var(--purple);
      color: #fff;
      box-shadow: 0 2px 16px rgba(86,32,193,0.35);
    }
    .btn-email:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(86,32,193,0.5); background: var(--purple-light); }
    .google-icon {
      width: 20px;
      height: 20px;
      flex-shrink: 0;
    }
    .email-icon {
      width: 20px;
      height: 20px;
      flex-shrink: 0;
      fill: none;
      stroke: #fff;
      stroke-width: 2;
    }
    .hero__legal {
      font-size: 11px;
      color: rgba(255,255,255,0.35);
      max-width: 420px;
      margin: 0 auto 48px;
      line-height: 1.5;
      position: relative;
    }
    .hero__legal a { color: rgba(255,255,255,0.55); text-decoration: underline; }

    /* Category pills */
    .hero__categories {
      position: relative;
      overflow: hidden;
    }
    .hero__categories-label {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-muted);
      letter-spacing: 0.08em;
      text-transform: uppercase;
      margin-bottom: 14px;
    }
    .categories-scroll {
      display: flex;
      gap: 10px;
      overflow-x: auto;
      scrollbar-width: none;
      padding: 4px 0 8px;
      justify-content: center;
      flex-wrap: wrap;
    }
    .categories-scroll::-webkit-scrollbar { display: none; }
    .category-pill {
      flex-shrink: 0;
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      color: rgba(255,255,255,0.8);
      font-size: 13px;
      font-weight: 600;
      padding: 7px 16px;
      border-radius: 100px;
      cursor: pointer;
      transition: background 0.2s, border-color 0.2s, color 0.2s, transform 0.15s;
      text-decoration: none;
      white-space: nowrap;
    }
    .category-pill:hover {
      background: rgba(85,218,155,0.12);
      border-color: rgba(85,218,155,0.3);
      color: var(--green);
      transform: translateY(-1px);
    }

    /* ── Features ── */
    .features {
      padding: 96px 24px;
      background: #fafafc;
    }
    .section-label {
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 12px;
    }
    .section-title {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      line-height: 1.12;
      letter-spacing: -1px;
      color: #111;
    }
    .section-title--white { color: #fff; }
    .features__header {
      text-align: center;
      max-width: 560px;
      margin: 0 auto 60px;
    }
    .features__grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 24px;
      max-width: 1200px;
      margin: 0 auto;
    }
    .feature-card {
      background: #fff;
      border-radius: var(--radius-lg);
      padding: 32px 28px;
      border: 1px solid var(--border-light);
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .feature-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
    .feature-icon {
      width: 52px;
      height: 52px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
      margin-bottom: 20px;
    }
    .feature-card:nth-child(1) .feature-icon { background: rgba(85,218,155,0.12); }
    .feature-card:nth-child(2) .feature-icon { background: rgba(86,32,193,0.1); }
    .feature-card:nth-child(3) .feature-icon { background: rgba(255,107,107,0.1); }
    .feature-card:nth-child(4) .feature-icon { background: rgba(255,193,7,0.1); }
    .feature-card h3 {
      font-size: 18px;
      font-weight: 700;
      color: #111;
      margin-bottom: 8px;
      letter-spacing: -0.3px;
    }
    .feature-card p {
      font-size: 14px;
      color: #666;
      line-height: 1.6;
    }

    /* ── Stats ── */
    .stats {
      background: var(--dark-section);
      padding: 80px 24px;
      position: relative;
      overflow: hidden;
    }
    .stats::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse 80% 100% at 50% 50%, rgba(86,32,193,0.12) 0%, transparent 70%);
      pointer-events: none;
    }
    .stats__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0;
      max-width: 900px;
      margin: 0 auto;
      position: relative;
    }
    .stat-item {
      text-align: center;
      padding: 32px 16px;
      border-right: 1px solid var(--border);
    }
    .stat-item:last-child { border-right: none; }
    .stat-number {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 800;
      color: #fff;
      letter-spacing: -2px;
      line-height: 1;
      margin-bottom: 8px;
    }
    .stat-number .accent { color: var(--green); }
    .stat-label {
      font-size: 14px;
      font-weight: 500;
      color: var(--text-muted);
    }

    /* ── Courses ── */
    .courses {
      padding: 96px 0 80px;
      background: #fff;
    }
    .courses__header {
      text-align: center;
      max-width: 600px;
      margin: 0 auto 40px;
      padding: 0 24px;
    }
    .courses__header .section-title { margin-top: 8px; }

    /* Tabs */
    .tabs-wrapper {
      position: relative;
      margin-bottom: 40px;
    }
    .tabs-scroll {
      display: flex;
      gap: 4px;
      overflow-x: auto;
      scrollbar-width: none;
      padding: 0 24px 4px;
      border-bottom: 2px solid var(--border-light);
    }
    .tabs-scroll::-webkit-scrollbar { display: none; }
    .tab-btn {
      flex-shrink: 0;
      background: none;
      border: none;
      font-family: inherit;
      font-size: 14px;
      font-weight: 600;
      color: #888;
      padding: 10px 16px;
      cursor: pointer;
      border-bottom: 2px solid transparent;
      margin-bottom: -2px;
      transition: color 0.2s, border-color 0.2s;
      white-space: nowrap;
    }
    .tab-btn:hover { color: #111; }
    .tab-btn.active { color: var(--purple); border-bottom-color: var(--purple); }

    /* Course Grid */
    .courses-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
      gap: 20px;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      min-height: 300px;
    }
    .course-card {
      background: #fff;
      border-radius: var(--radius-lg);
      border: 1px solid var(--border-light);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }
    .course-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.1); }
    .course-card.hidden { display: none; }
    .course-thumb {
      height: 160px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      position: relative;
      overflow: hidden;
    }
    .course-thumb::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.25) 100%);
    }
    .course-thumb .thumb-icon {
      position: relative;
      z-index: 1;
      filter: drop-shadow(0 2px 8px rgba(0,0,0,0.2));
    }
    .course-thumb-g1 { background: linear-gradient(135deg, #FF6B6B 0%, #FF8E53 100%); }
    .course-thumb-g2 { background: linear-gradient(135deg, #4158D0 0%, #C850C0 100%); }
    .course-thumb-g3 { background: linear-gradient(135deg, #0BA360 0%, #3CBA92 100%); }
    .course-thumb-g4 { background: linear-gradient(135deg, #5620C1 0%, #9B59B6 100%); }
    .course-thumb-g5 { background: linear-gradient(135deg, #F09819 0%, #EDDE5D 100%); }
    .course-thumb-g6 { background: linear-gradient(135deg, #E44D26 0%, #F16529 100%); }
    .course-thumb-g7 { background: linear-gradient(135deg, #1A1A2E 0%, #16213E 50%, #0F3460 100%); }
    .course-thumb-g8 { background: linear-gradient(135deg, #8E2DE2 0%, #4A00E0 100%); }
    .course-body { padding: 16px 18px 20px; flex: 1; display: flex; flex-direction: column; gap: 4px; }
    .course-title {
      font-size: 14px;
      font-weight: 700;
      color: #111;
      line-height: 1.4;
      letter-spacing: -0.2px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .course-instructor { font-size: 13px; color: #666; font-weight: 500; margin-top: 4px; }
    .course-meta {
      display: flex;
      gap: 12px;
      margin-top: auto;
      padding-top: 12px;
      border-top: 1px solid var(--border-light);
    }
    .course-meta span {
      font-size: 12px;
      color: #888;
      display: flex;
      align-items: center;
      gap: 4px;
    }
    .no-courses-msg {
      grid-column: 1 / -1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 60px 20px;
      color: #999;
      gap: 8px;
    }
    .no-courses-msg span:first-child { font-size: 40px; }
    .no-courses-msg span:last-child { font-size: 15px; font-weight: 500; }

    /* ── Creative Feed ── */
    .creative-feed {
      padding: 96px 24px;
      background: #fafafc;
    }
    .creative-feed__inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .creative-feed__header {
      max-width: 540px;
      margin-bottom: 52px;
    }
    .creative-feed__grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
    }
    .feed-card {
      background: #fff;
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--border-light);
      display: flex;
      flex-direction: column;
      gap: 14px;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .feed-card:hover { transform: translateY(-3px); box-shadow: 0 10px 32px rgba(0,0,0,0.07); }
    .feed-card-dot {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
    }
    .feed-card:nth-child(1) .feed-card-dot { background: rgba(255,107,107,0.1); }
    .feed-card:nth-child(2) .feed-card-dot { background: rgba(86,32,193,0.1); }
    .feed-card:nth-child(3) .feed-card-dot { background: rgba(85,218,155,0.12); }
    .feed-card h3 { font-size: 20px; font-weight: 800; color: #111; letter-spacing: -0.4px; }
    .feed-card p { font-size: 15px; color: #555; line-height: 1.65; }

    /* ── Teachers ── */
    .teachers {
      padding: 96px 0 80px;
      background: var(--hero-bg);
      overflow: hidden;
    }
    .teachers__header {
      padding: 0 24px;
      max-width: 1200px;
      margin: 0 auto 48px;
    }
    .teachers__header .section-title--white { margin-top: 8px; }
    .teachers__subtitle {
      font-size: 16px;
      color: var(--text-muted);
